const clock=new THREE.Clock();
function frame(){requestAnimationFrame(frame);const dt=Math.min(clock.getDelta(),.04);runClock+=dt;
 if(playing){if(roundPause>0){roundPause-=dt;if(roundPause<=0){round++;progress=0;spawnClock=.8;enemies.forEach(e=>scene.remove(e.mesh));enemies.length=0;announce(`РАУНД ${round} · СНОВА В БОЙ!`);updateHUD()}}else{
  const turbo=keys.boost&&boost<1.6;speed=turbo?27:19;boost=turbo?Math.min(1.6,boost+dt):Math.max(0,boost-dt*.72);progress+=speed*dt;spawnClock-=dt;attackCooldown=Math.max(0,attackCooldown-dt);invuln=Math.max(0,invuln-dt);if(player.userData.punch)player.userData.punch=Math.max(0,player.userData.punch-dt);
  if(spawnClock<=0&&progress<roundLength-18){let lane=Math.floor(Math.random()*3);if(lane===targetLane&&Math.random()<.65)lane=(lane+1+Math.floor(Math.random()*2))%3;makeEnemy(lane,-rand(31,45));spawnClock=rand(1.55,2.45)}
  if(progress>roundLength-95&&!enemies.some(e=>e.boss)&&round===2)makeEnemy(Math.floor(Math.random()*3),-34,true);
  if(progress>=roundLength){if(round===1){roundPause=2.3;announce('ФИНИШ! ГОТОВЬСЯ К РАУНДУ 2');}else{updateHUD();endGame(true)}}
  const targetX=laneX[targetLane];player.position.x+=(targetX-player.position.x)*Math.min(1,dt*9);player.rotation.z=-(targetX-player.position.x)*.18;player.rotation.x=Math.sin(runClock*10)*.012;
  if(player.userData.punch>0){const arm=player.children.find(c=>c.geometry?.type==='CapsuleGeometry'&&c.position.x>0);if(arm)arm.rotation.z=.48+Math.sin(player.userData.punch/.25*Math.PI)*.9}
  for(const w of player.userData.wheels)w.rotation.x-=speed*dt*1.1;
  const worldShift=speed*dt;
  for(const d of roadBits){d.position.z+=worldShift;if(d.position.z>15)d.position.z-=120}
  for(const c of city){c.position.z+=worldShift*.92;if(c.position.z>14)c.position.z-=125}
  for(const l of lamps){l.position.z+=worldShift;if(l.position.z>15)l.position.z-=120}
  for(let i=enemies.length-1;i>=0;i--){const e=enemies[i];e.mesh.position.z+=worldShift*(e.boss?.78:.87);e.mesh.position.x+=(laneX[e.lane]-e.mesh.position.x)*dt*3;e.mesh.rotation.z=Math.sin(runClock*5+i)*.025;for(const w of e.mesh.userData.wheels)w.rotation.x-=worldShift*.85;if(e.hit>0){e.hit-=dt;e.mesh.position.x+=Math.sin(runClock*35)*.04}if(e.mesh.position.z>1.15){if(invuln<=0&&e.lane===targetLane){health--;invuln=1.1;shake=.35;effect(e.mesh.position.x,1.4,1.8,0xff3d6c,14);announce('СТОЛКНОВЕНИЕ!');if(health<=0){scene.remove(e.mesh);enemies.splice(i,1);updateHUD();endGame(false);break}}else if(e.lane!==targetLane)score+=40;scene.remove(e.mesh);enemies.splice(i,1)}}
  for(let i=particles.length-1;i>=0;i--){const p=particles[i];p.life-=dt;p.mesh.position.addScaledVector(p.v,dt);p.v.y-=8*dt;p.mesh.scale.multiplyScalar(.985);if(p.life<=0){scene.remove(p.mesh);particles.splice(i,1)}}
  shake=Math.max(0,shake-dt);const jx=shake?rand(-shake,shake):0;camera.position.x+=(player.position.x*.27-camera.position.x)*dt*2.7+jx;camera.position.y=5.4+(turbo?Math.sin(runClock*28)*.06:0);camera.position.z=11.8;camera.lookAt(player.position.x*.22,1.35,-4.6);if(turbo){blueLight.intensity=30;pinkLight.intensity=27}else{blueLight.intensity=20;pinkLight.intensity=23}
  updateHUD();
 }
 }
 // subtle idle showroom camera while title is open
 else{player.position.y=Math.sin(runClock*1.6)*.035;player.rotation.z=Math.sin(runClock*.8)*.04;camera.position.x=Math.sin(runClock*.25)*.35;camera.lookAt(0,1.2,-4)}
 renderer.render(scene,camera)}
frame();
</script>
</body>
</html>

